// Click counter: pure pieces, unit-tested in counter.test.ts.

/** What the visitor is told when the increment call fails (the database function rate-limits per IP). */
export function counterErrorMessage(error: { message?: string } | null | undefined): string {
  if (error?.message?.includes('Rate limit exceeded')) return 'You have reached the limit of 50 clicks per 24 hours.';
  return 'An error occurred. Please try again later.';
}

/** The counter as shown: 1234 -> "1,234" (the visitor's own locale, as before). */
export function formatCount(count: number): string {
  return count.toLocaleString();
}
