import { BaseElement } from '../../common/base-element';
import { getSupabaseClient } from '../../common/supabase-client';
import { counterErrorMessage, formatCount } from './counter';

/**
 * <rg-click-counter>: "Help us reach our goal of 1,000 emails sharing REAL!!" with a button that
 * adds one to a shared counter. The counter lives in the `global_counter` table (public read) and
 * the `increment_counter()` function, which logs the visitor's IP and allows 50 clicks per 24 hours.
 *
 * Markup, wording and inline styles are the original widget's; it now lives in a Shadow DOM, so the
 * page's CSS cannot restyle it.
 */
export class RgClickCounter extends BaseElement {
  constructor() {
    super(':host { display: block; }');
  }

  connectedCallback(): void {
    this.setHtml(`
<div id="counter-widget" style="text-align: center; padding: 0; font-family: Verdana, Geneva, sans-serif;">
  <h3 style="margin-top: 0;">Help us reach our goal of 1,000 emails sharing REAL!!</h3>
  <p>Click this button if you sent a message to track a message sent!</p>
  <h2 style="font-size: 1.3rem; margin-bottom: 15px;">Already sent: <span id="counter-value">...</span></h2>

  <button id="increment-btn" style="padding: 20px 56px; font-size: 1.1rem; cursor: pointer; background-color: #000; color: #fff; border: none; border-radius: 8px; transition: background-color 0.2s;">
    One message sent!
  </button>

  <p id="counter-msg" style="color: #e63946; margin-top: 15px; font-weight: bold; min-height: 20px; display: none;"></p>

  <p style="margin-top: 45px;">Ok, be cool. We know you can misuse this button, but we are trusting you here.</p>
</div>`);

    const counterValueEl = this.$('#counter-value')!;
    const incrementBtn = this.$<HTMLButtonElement>('#increment-btn')!;
    const msgEl = this.$('#counter-msg')!;
    const db = getSupabaseClient();

    const fetchCount = async () => {
      const { data, error } = await db.from('global_counter').select('count').eq('id', 1).single();
      if (data) {
        counterValueEl.innerText = formatCount(data.count);
      } else {
        console.error('Error fetching count:', error);
        counterValueEl.innerText = 'Error';
      }
    };

    incrementBtn.addEventListener('click', async () => {
      // Disable the button meanwhile, to prevent double-clicking
      incrementBtn.disabled = true;
      incrementBtn.style.opacity = '0.7';
      msgEl.style.display = 'none';

      const { data, error } = await db.rpc('increment_counter');

      if (error) {
        console.error('RPC Error:', error);
        msgEl.innerText = counterErrorMessage(error);
        msgEl.style.display = 'block';
      } else if (data !== null) {
        counterValueEl.innerText = formatCount(data as number);
        // Fun visual feedback
        incrementBtn.style.backgroundColor = '#4CAF50';
        setTimeout(() => {
          incrementBtn.style.backgroundColor = '#000';
        }, 500);
      }

      incrementBtn.disabled = false;
      incrementBtn.style.opacity = '1';
    });

    void fetchCount();
  }
}

if (!customElements.get('rg-click-counter')) customElements.define('rg-click-counter', RgClickCounter);
